class Solution {
public:
    ListNode* deleteDuplicatesUnsorted(ListNode* head) {
        unordered_map<int, int> freq;

        // Pass 1: Count frequencies.
        ListNode* curr = head;

        while (curr != nullptr) {
            freq[curr->val]++;
            curr = curr->next;
        }

        ListNode dummy(0);
        dummy.next = head;

        ListNode* prev = &dummy;
        curr = head;

        // Pass 2: Unlink all duplicate values.
        while (curr != nullptr) {
            if (freq[curr->val] > 1) {
                curr = curr->next;
                prev->next = curr;
            } else {
                prev = curr;
                curr = curr->next;
            }
        }

        return dummy.next;
    }
};
